@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font:13px/1.5 Arial,sans-serif;color:#202839;max-width:960px;margin:24px auto;padding:20px;background:#fff}header{display:flex;justify-content:space-between;gap:24px;border-bottom:2px solid #29344a;padding-bottom:18px}h1{font-size:24px;margin:5px 0}.company{font-size:16px;font-weight:600;margin:0}.identity{text-align:right}.status{display:inline-block;padding:4px 10px;border:1px solid #999;border-radius:5px;font-weight:700;text-transform:uppercase}.warning{padding:12px 16px;border:1px solid #bd8a31;background:#fff8e9;margin:20px 0;font-weight:600}.metadata{display:grid;grid-template-columns:130px 1fr;gap:8px 18px;margin:22px 0}.metadata dt{color:#596171}.metadata dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;margin:24px 0}th,td{padding:10px 9px;border-bottom:1px solid #d9dce1;text-align:left;vertical-align:top;overflow-wrap:anywhere}thead th{background:#f3f4f6;font-size:11px;text-transform:uppercase;letter-spacing:.04em}thead{display:table-header-group}tr{break-inside:avoid}.numeric{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}tfoot th{border-top:2px solid #29344a;background:#f3f4f6}small{display:block;color:#626b79}.signatures{display:flex;justify-content:space-between;gap:20px;margin-top:56px;break-inside:avoid}.note{font-size:11px;color:#596171;margin-top:28px}.toolbar{display:flex;justify-content:flex-end;margin-bottom:20px}.toolbar button{border:1px solid #bbb;border-radius:6px;padding:9px 16px;background:#f5f6f8;cursor:pointer}@media print{body{max-width:none;margin:0;padding:0}.toolbar{display:none}.warning{background:#fff}a{color:inherit;text-decoration:none}}@media(max-width:600px){body{padding:12px}header{flex-direction:column}.identity{text-align:left}.signatures{flex-wrap:wrap}.metadata{grid-template-columns:100px 1fr}}
