<body><div class="toolbar"><button type="button" onclick="window.print()">Print journal</button></div><header><div><p class="company">{{ $company->name }}</p><h1>{{ !empty($journal['imprest']) ? 'Imprest Advance Voucher' : ($journal['kind'] === 'opening' ? 'Opening Balance Journal' : ($journal['kind'] === 'reversal' ? 'Reversal Journal' : 'Journal Entry')) }}</h1><small>Amounts in {{ $book->currency }}</small></div><div class="identity"><strong>{{ $journal['number'] }}</strong><p><span class="status">{{ !empty($journal['imprest']->void) ? 'CANCELLED' : ($journal['status'] === 'draft' ? 'NON-POSTED / DRAFT' : $journal['status']) }}</span></p></div></header><p>Transaction currency: {{ $journal['currency'] ?? $book->currency }} · Rate: {{ $journal['exchange_rate'] ?? 1 }} {{ $book->currency }} per unit. Ledger totals in {{ $book->currency }}.</p>
